"""Reproducible export (SPEC §11): reproduce_<run_id>.py, generated by our code from templates/reproduce.py.tmpl.

The script bundles our analysis code verbatim (science modules, the tool layer, the deterministic checks and the
plots), the dataset config, and the run's tool calls and stored values. It replays every stored tool call in
order with the same parameters and seed, and compares every value. Nothing in it is written by a model: the
only run-specific parts are JSON data (plan, call arguments, values) and the question in a docstring.
"""
from __future__ import annotations

import json
import re
from pathlib import Path

from app.agent.report import PLACEHOLDER
from app.config import load_config

APP_DIR = Path(__file__).resolve().parents[1]
TEMPLATE = Path(__file__).with_name("templates") / "reproduce.py.tmpl"
# Bundled, verbatim, as an importable package (app/config.py is generated by the script itself).
BUNDLED = ["__init__.py", "science/__init__.py", "science/residues.py", "science/loader.py", "science/contacts.py",
           "science/distances.py", "science/stats.py", "science/contact_stats.py", "science/native_contacts.py",
           "science/flexibility.py", "agent/__init__.py", "agent/tools.py", "agent/report.py",
           "provenance/__init__.py", "provenance/plots.py"]
REQUIREMENTS = {
    "adk_equilibrium": "MDAnalysis, MDAnalysisData, NumPy, SciPy, matplotlib",
    # The transition path ships with MDAnalysisTests (SPEC §5b), so a transition run also needs it.
    "adk_transition": "MDAnalysis, MDAnalysisTests (the dataset), NumPy, SciPy, matplotlib",
}


def _texts(run: dict) -> list[str]:
    rep = run.get("report") or {}
    out = [f.get("text", "") for f in rep.get("findings", [])] + [f.get("plain") or "" for f in run.get("findings", {}).values()]
    for k in ("headline", "interpretation"):
        out.append(((rep.get(k) or {}).get("segments") and "".join(
            "{{" + s["path"] + "}}" if s.get("pid") else s["text"] for s in rep[k]["segments"])) or "")
    for k in ("hypotheses", "caveats", "gaps", "background"):
        out += ["".join("{{" + s["path"] + "}}" if s.get("pid") else s["text"] for s in x.get("segments", []))
                for x in rep.get(k, [])]
    return out


def cited_values(run: dict) -> list[str]:
    """Every placeholder the report's text resolves (e.g. 'r2.HSE134-ASP118.delta'), in order, without repeats."""
    seen: list[str] = []
    for t in _texts(run):
        for m in PLACEHOLDER.finditer(t):
            if m[1] not in seen:
                seen.append(m[1])
    return seen


def run_payload(run: dict) -> dict:
    """The run data the script embeds: plan, the stored tool calls in order, and every stored value."""
    calls = [{"turn": t["turn"], "tool": t["tool"], "arguments": t.get("arguments") or "{}",
              "provenance_id": t["provenance_id"], "status": t["status"]}
             for t in run["turns"] if t.get("provenance_id")]
    values = {pid: {k: v["v"] for k, v in r["values"].items()} for pid, r in run["results"].items() if r["status"] == "ok"}
    prov = next((r["provenance"] for r in run["results"].values() if r.get("provenance")), {})
    return {"run_id": run["run_id"], "question": run["question"], "plan": run["plan"], "calls": calls, "values": values,
            "cited": cited_values(run), "dataset_hashes": prov.get("dataset_hashes"),
            "library_versions": prov.get("library_versions"), "seed": prov.get("seed")}


def _docstring_safe(text: str) -> str:
    return re.sub(r"\s+", " ", text.replace("\\", "/").replace('"""', "'''"))[:300]


def build_script(run: dict, config: dict | None = None) -> str:
    """The reproduce script for a saved run (a Run.as_dict() / investigations/<id>.json)."""
    if not run.get("turns") or not run.get("results"):
        raise ValueError("this run has no tool results to reproduce")
    payload = run_payload(run)
    ds = run["plan"]["dataset"]
    sources = {f"app/{rel}": (APP_DIR / rel).read_text(encoding="utf-8") for rel in BUNDLED}
    src = "{\n" + "".join(f"    {k!r}: {v!r},\n" for k, v in sources.items()) + "}"
    out = TEMPLATE.read_text(encoding="utf-8")
    for token, value in {
        "@@RUN_JSON@@": repr(json.dumps(payload, ensure_ascii=False)),
        "@@CONFIG_JSON@@": repr(json.dumps(config or load_config(), ensure_ascii=False, default=str)),
        "@@SOURCES@@": src,
        "@@REQUIREMENTS@@": REQUIREMENTS.get(ds, REQUIREMENTS["adk_equilibrium"]),
        "@@QUESTION@@": _docstring_safe(run["question"]),
        "@@DATASET@@": ds,
        "@@RUN_ID@@": re.sub(r"[^A-Za-z0-9_-]", "", run["run_id"]),
    }.items():
        out = out.replace(token, value)
    return out


def script_name(run_id: str) -> str:
    return f"reproduce_{re.sub(r'[^A-Za-z0-9_-]', '', run_id)}.py"
